// Deduplicação — ignora o mesmo erro por 5 min
const staticData = $getWorkflowStaticData('global');
const errKey = 'err_' + (($json.body?.error_message || '').substring(0, 80) + '|' + ($json.body?.route || '')).replace(/\W+/g, '_');
const lastSent = staticData[errKey] || 0;
if (Date.now() - lastSent < 5 * 60 * 1000) return [];
staticData[errKey] = Date.now();

// Extrair caminho do arquivo a partir do stack trace
const stack = $json.body?.stack_trace || '';
let filePath = null;
let lineNumber = null;
for (const line of stack.split('\n')) {
  const m = line.match(/\(\/app\/(.+?):(\d+):\d+\)/);
  if (m && !m[1].includes('node_modules')) {
    filePath = m[1];
    lineNumber = parseInt(m[2]);
    break;
  }
}

return [{ json: {
  error_message: $json.body?.error_message || 'Erro desconhecido',
  stack_trace:   $json.body?.stack_trace   || '',
  route:         $json.body?.route         || '',
  method:        $json.body?.method        || 'GET',
  request_body:  $json.body?.request_body  || '{}',
  timestamp:     $json.body?.timestamp     || new Date().toISOString(),
  file_path:     filePath,
  line_number:   lineNumber,
} }];

const data = $('Extrair Path').first().json;

// Código fonte (pode ter falhado)
let sourceCode = 'Código não disponível';
try {
  const cd = $('Buscar Código Fonte').first().json;
  if (cd.content) sourceCode = cd.content;
} catch(e) {}

// Logs recentes (pode ter falhado)
let logsRecentes = 'Logs não disponíveis';
try {
  const ld = $('Buscar Logs Recentes').first().json;
  if (ld.logs) logsRecentes = ld.logs;
} catch(e) {}

const loc = data.file_path
  ? `${data.file_path}${data.line_number ? ':' + data.line_number : ''}`
  : 'arquivo não identificado';

const chatInput = `Você é um engenheiro sênior de Node.js analisando um erro em produção do backend Jinx (Express.js) da Purg.

ERRO DETECTADO:
- Mensagem: ${data.error_message}
- Rota: ${data.method} ${data.route}
- Horário: ${data.timestamp}
- Localização: ${loc}
- Body da requisição: ${data.request_body}

STACK TRACE:
${data.stack_trace.substring(0, 1500)}

CÓDIGO FONTE (${loc}):
${sourceCode.substring(0, 3000)}

LOGS RECENTES (últimas 80 linhas):
${logsRecentes.substring(0, 1500)}

Responda em português com EXATAMENTE estas 3 seções:

🔍 CAUSA RAÍZ
Explique em 2-3 frases o que causou o erro e por quê.

⚠️ IMPACTO
Quais funcionalidades ou usuários foram afetados por este erro.

🛠️ CORREÇÃO PARA O CLAUDE
Escreva um prompt pronto para colar no Claude Code, em português, especificando: arquivo, linha aproximada, e exatamente o que mudar no código. Seja direto e técnico, sem introdução.`;

return [{ json: { ...data, chatInput } }];

const analysis = ($json.text || $json.output || $json.response || 'Análise não disponível').trim();
const data = $('Extrair Path').first().json;

const ts = new Date(data.timestamp).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const loc = data.file_path
  ? `\`${data.file_path}${data.line_number ? ':' + data.line_number : ''}\``
  : '';

const header = [
  `🚨 *Erro em Produção — Jinx*`,
  `📅 ${ts}`,
  `🌐 \`${data.method} ${data.route}\``,
  loc ? `📁 ${loc}` : '',
].filter(Boolean).join('\n');

const footer = '\n\n---\n⚠️ _Análise preliminar gerada pelo Gemini. Cole a sugestão acima no Claude para ele se aprofundar e aplicar a correção._';

const msg = header + '\n\n' + analysis + footer;
return [{ json: { text: msg.substring(0, 4090) } }];

